 Mug Set of 2\' when o.sku = \'CSEECPBMRSE2\' then \'Eclipse Collection Pasta Bowl (Set of 2)\' when o.sku = \'CSERFAFCTBESE2\' then \'Rustic Facet and Flow Collection Tumbler (Set of 2)\' when o.sku = \'CSEECSMBESE2\' then \'Scallop Coffee Mug (Set of 2)\' when o.sku = \'CSEECCMMRSE2\' then \'Eclipse Collection Coffee Mug (Set of 2)\' when o.sku = \'CSERFAFCSBBESE3\' then \'Rustic Facet and Flow Collection Small Serving bowl Set of 2\' else coalesce(o.product_name, a.product_name) end as product_name, coalesce( c.PRODUCT_TYPES, case when o.sku in (\'CSEECSGSMBESE2\', \'CSEECSCMBESE2\', \'CSEECPBMRSE2\', \'CSERFAFCTBESE2\', \'CSEECSMBESE2\', \'CSEECCMMRSE2\', \'CSERFAFCSBBESE3\') then \'Ceramics\' else a.category_name end) as category_name, o.quantity, o.quantity * pp.nlc as Revenue, o.quantity * pp.nlc_without_tax as taxable_value from ( select o.*, coalesce(a.master_sku, o.sku_number) as sku, b.product_name from ( select date(date) as order_Date, case when \"Brand Name\" = \'YFL Home\' then \'YFL\' end as brand_name, \"SKU Number\" as sku_number, CITY, \'Zepto Secondary\' as marketplace, sum(\"Sales (Qty) - Units\") as quantity, sum(\"Gross Merchandise Value\") as Revenue from hox_db.maplemonk.HOX_Zepto_YFL_sales where \"Brand Name\" = \'YFL Home\' group by 1,2,3,4,5 union all select date(date) as order_Date, case when \"Brand Name\" = \'Cüraa\' then \'SevenChef\' end as brand_name, \"SKU Number\" as sku_number, CITY, \'Zepto Secondary\' as marketplace, sum(\"Sales (Qty) - Units\") as quantity, sum(\"Gross Merchandise Value\") as Revenue from hox_db.maplemonk.HOX_ZEPTO_SEVENCHEF_SALES group by 1,2,3,4,5 union all SELECT CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', (STARTDATE::TIMESTAMP))::date AS order_Date, \'SevenChef\' as brand_name, asin as sku_number, \'retailEz\' as CITY, \'RetailEz Secondary\' as marketplace, (sum(ifnull(SHIPPEDUNITS,0)) - sum(ifnull(CUSTOMERRETURNS,0))) as quantity, sum(0) as revenue from hox_db.maplemonk.hox_sevenchef_get_vendor_sales_report group by 1, 2, 3, 4, 5 ) as o left join skus a on lower(o.sku_number) = lower(a.marketplace_sku) left join product_names b on lower(coalesce(a.master_sku, o.sku_number)) = lower(b.component_sku) )as o left join product_price pp on o.sku = pp.sku_code and lower(o.marketplace) = lower(pp.marketplace) left join product_base a on lower(o.sku) = lower(a.skucode) left join product_base_sheet c on lower(o.sku) = lower(c.SKU_CODE);",
